const errors = [];
const workspace = $json.workspace && typeof $json.workspace === 'object' && !Array.isArray($json.workspace)
  ? $json.workspace
  : {};

if ($json.route !== 'workspace.created') errors.push('route must be workspace.created');
if ($json.status !== 'ready') errors.push('status must be ready');

const requiredStrings = [
  'workspace_uuid',
  'workspace_name',
  'novel_uuid',
  'novel_slug',
  'novel_title',
  'novel_genre',
  'root_folder_name',
  'workspace_version',
  'created_at',
  'created_by',
];

for (const field of requiredStrings) {
  if (typeof workspace[field] !== 'string' || !workspace[field].trim()) {
    errors.push(`workspace.${field} must be a non-empty string`);
  }
}

if (!Array.isArray(workspace.folder_manifest) || workspace.folder_manifest.length === 0) {
  errors.push('workspace.folder_manifest must be a non-empty array');
}
if (!Array.isArray(workspace.file_manifest) || workspace.file_manifest.length === 0) {
  errors.push('workspace.file_manifest must be a non-empty array');
}
if (errors.length > 0) throw new Error(`Invalid workspace contract: ${errors.join('; ')}`);

return [{ json: { workspace } }];

const workspace = $json.workspace;
const folderRecords = workspace.folder_manifest.map((folder_name, index) => ({
  record_type: 'folder',
  sequence: index + 1,
  name: folder_name,
  parent: workspace.root_folder_name,
}));
const fileRecords = workspace.file_manifest.map((file_name, index) => ({
  record_type: 'file',
  sequence: index + 1,
  name: file_name,
  parent: workspace.root_folder_name,
}));

return [{
  json: {
    ...$json,
    persistence_manifest: [...folderRecords, ...fileRecords],
  },
}];

const workspace = $json.workspace;
const persistedAt = new Date().toISOString();

return [{
  json: {
    persistence: {
      persistence_key: `workspace:${workspace.workspace_uuid}`,
      workspace_uuid: workspace.workspace_uuid,
      novel_uuid: workspace.novel_uuid,
      root_folder_name: workspace.root_folder_name,
      workspace_version: workspace.workspace_version,
      persistence_version: '1.0',
      persistence_mode: 'contract_only',
      persistence_status: 'prepared',
      record_count: $json.persistence_manifest.length,
      manifest: $json.persistence_manifest,
      prepared_at: persistedAt,
      prepared_by: workspace.created_by,
    },
  },
}];

const persistence = $json.persistence;

return [{
  json: {
    route: 'workspace.persistence.prepared',
    status: 'ready',
    persistence,
    next_workflow: 'WF-003-P03',
  },
}];
